return ['domain'=>'wp-checksum-verifier','plural-forms'=>'nplurals=1; plural=0;','language'=>'ja','project-id-version'=>'WP Checksum Verifier 0.9.0','pot-creation-date'=>'2026-10-03T06:42:41+00:00','po-revision-date'=>'2026-10-03 00:00+0000','messages'=>['WP Checksum Verifier'=>'WP Checksum Verifier','https://github.com/lunaluna/wp-checksum-verifier'=>'https://github.com/lunaluna/wp-checksum-verifier','WordPress コア・プラグイン・テーマ・MU プラグインの checksum を日次で検証し、改ざんを検出するプラグイン.'=>'WordPress コア・プラグイン・テーマ・MU プラグインの checksum を日次で検証し、改ざんを検出するプラグイン.','lunaluna_dev'=>'lunaluna_dev','https://profiles.wordpress.org/lunaluna_dev/'=>'https://profiles.wordpress.org/lunaluna_dev/','Checksum Verifier'=>'Checksum Verifier','Run History'=>'実行履歴','Findings'=>'検出結果','Suppressions'=>'抑制','WP Checksum Verifier: no alert recipients are set. Findings are not being emailed to anyone. Set at least one address on the WP Checksum Verifier settings screen.'=>'WP Checksum Verifier: アラートの宛先が設定されていません。検出結果は誰にもメール送信されません。WP Checksum Verifier の設定画面で、宛先を1件以上設定してください。','WP Checksum Verifier: the last alert email failed to send.'=>'WP Checksum Verifier: 直近のアラートメールの送信に失敗しました。','WP Checksum Verifier: the last alert email failed to send: %s'=>'WP Checksum Verifier: 直近のアラートメールの送信に失敗しました: %s','WP Checksum Verifier: %d target(s) cannot be compared with their source because the GitHub token is invalid, expired or lacks permission. They are monitored by file-change tracking meanwhile. Check the GitHub token (the WPCV_GITHUB_TOKEN constant or the wpcv_github_token filter).'=>'WP Checksum Verifier: GitHub のトークンが無効・失効している、または権限が足りないため、%d 件の照合対象を照合元と比較できません。その間はファイルの変化(stat 差分検知)で監視しています。GitHub のトークン(WPCV_GITHUB_TOKEN 定数または wpcv_github_token フィルター)を確認してください。','WP Checksum Verifier is active only on this site, not network-wide. Its scheduled checks do not run and its screens are not available from the Network Admin. Network-activate it to use it on a multisite network.'=>'WP Checksum Verifier はネットワーク全体ではなく、このサイトだけで有効化されています。定時の検証は実行されず、画面もネットワーク管理から使えません。マルチサイトのネットワークで使うには、ネットワーク有効化してください。','Open Network Admin plugins'=>'ネットワーク管理のプラグイン一覧を開く','The suppression rule has been created. It will apply starting with the next run.'=>'抑制ルールを作成しました。次の実行から適用されます。','No runs have been recorded yet.'=>'まだ実行が記録されていません。','Dimension'=>'種別','All'=>'すべて','Status'=>'ステータス','Severity'=>'重大度','Diff'=>'差分','Show suppressed'=>'抑制済みを表示','Show closed'=>'終了したものを表示','Filter'=>'絞り込み','No findings match the current filters.'=>'条件に一致する検出結果はありません。','Target'=>'照合対象','Active on'=>'有効なサイト','Path'=>'パス','Details'=>'詳細','Version'=>'バージョン','Suppressed'=>'抑制済み','Actions'=>'操作','Network-wide (all sites)'=>'ネットワーク全体(すべてのサイト)','Network-enabled, but not active on any site'=>'ネットワークで有効化済みですが、どのサイトでも使われていません','Not active on any site'=>'どのサイトでも有効ではありません','Not shown (the network has %d sites)'=>'表示していません(ネットワークのサイト数が %d 件あります)','%s (parent theme)'=>'%s(親テーマ)','and %d more'=>'ほか %d 件','%1$d of %2$d files changed (rolled up). Examples: %3$s'=>'%2$d 件中 %1$d 件のファイルが変更されました(まとめて表示)。例: %3$s','possible timestamp forgery (size changed but mtime did not)'=>'タイムスタンプの偽装の可能性(サイズは変わったが mtime は変わっていません)','%1$s (emailed %2$s)'=>'%1$s(メール送信済み: %2$s)','Reason (required)'=>'理由(必須)','Exclude this path'=>'このパスを除外','Approve this hash'=>'このハッシュを承認','Exclude entire target'=>'照合対象全体を除外','Rule #%d'=>'ルール #%d','This finding has no hash to approve.'=>'この検出結果には承認できるハッシュがありません。','Unknown action.'=>'不明な操作です。','A reason is required.'=>'理由は必須です。','Run history'=>'実行履歴','Run'=>'実行','Trigger'=>'実行契機','Started'=>'開始','Finished'=>'終了','Targets'=>'照合対象','Diff (New / Resolved / Continuing)'=>'差分(新規 / 解消 / 継続)','Alert'=>'アラート','« Previous'=>'« 前へ','Page %1$d of %2$d'=>'%2$d ページ中 %1$d ページ目','Next »'=>'次へ »','« Back to run history'=>'« 実行履歴に戻る','This run could not be found.'=>'この実行が見つかりません。','Run #%d'=>'実行 #%d','Deadline'=>'期限','%1$s (attempts: %2$d)'=>'%1$s(試行回数: %2$d)','New / Resolved / Continuing'=>'新規 / 解消 / 継続','%1$s (attempted: %2$s)'=>'%1$s(試行日時: %2$s)','Alert error'=>'アラートのエラー','Failed alert channels'=>'失敗したアラートの送信経路','View findings for this run'=>'この実行の検出結果を見る','No targets were recorded for this run.'=>'この実行では照合対象が記録されていません。','Reason'=>'理由','Files'=>'ファイル','Attempts'=>'試行回数','Diff mode'=>'差分モード','%1$d / %2$d'=>'%1$d / %2$d','Update events since the previous run'=>'前回の実行以降の更新イベント','No update events were recorded in this window.'=>'この期間に更新イベントは記録されていません。','Source'=>'ソース','Recorded at'=>'記録日時','By'=>'実行者','Automatic (cron/WP-CLI)'=>'自動(cron/WP-CLI)','Findings ended in this run'=>'この実行で終了した検出結果','No findings ended in this run.'=>'この実行で終了した検出結果はありません。','First seen in'=>'初回検出','%s — cannot be compared with the source; monitored by file-change tracking instead'=>'%s — 照合元と比較できないため、代わりにファイルの変化(stat 差分検知)で監視しています','Settings saved.'=>'設定を保存しました。','Some GitHub repository mappings were not saved:'=>'一部の GitHub リポジトリの対応付けは保存されませんでした:','A verification run has been scheduled.'=>'検証の実行を予約しました。','Daily run time (UTC)'=>'毎日の実行時刻(UTC)','The verification run starts automatically at this time every day (UTC). External HTTP mode (below) also uses this time to decide when to start the daily run.'=>'検証は毎日この時刻(UTC)に自動で始まります。外部 HTTP モード(下記)も、この時刻を毎日の実行を始める目安にします。','External HTTP time budget (seconds)'=>'外部 HTTP の時間予算(秒)','When an external scheduler calls POST /wp-json/wpcv/v1/run, this is how long (per request) it keeps advancing the run before returning. Keep it well under your host\'s max_execution_time.'=>'外部のスケジューラーが POST /wp-json/wpcv/v1/run を呼んだとき、1回のリクエストで実行を進める時間の上限です。ホストの max_execution_time よりかなり短くしてください。','Strict mode'=>'strict mode','Report readme.txt / readme.md changes as findings instead of suppressing them.'=>'readme.txt / readme.md の変更を、抑制せずに検出結果として報告する。','By default, changes limited to readme.txt/readme.md are treated as a low-risk "soft change" and suppressed automatically. Enable strict mode to see every difference, including those files.'=>'既定では、readme.txt / readme.md だけの変更は低リスクな「soft change」として自動的に抑制します。strict mode を有効にすると、これらのファイルを含むすべての差分を表示します。','Stat-based change detection'=>'stat 差分検知','Track file size and timestamps of plugins that cannot be verified against checksums, and report changes since the previous run.'=>'チェックサムで照合できないプラグインのファイルサイズとタイムスタンプを記録し、前回の実行からの変更を報告する。','Applies to custom or premium plugins and mu-plugin loaders that have no official checksums. The first run only records a baseline. When a plugin version changes, its baseline is rebuilt without reporting changes. File contents are not read unless content-hash comparison is also enabled below.'=>'公式のチェックサムが無い独自・有料のプラグインと、mu-plugin の loader が対象です。最初の実行ではベースラインを記録するだけです。プラグインのバージョンが変わると、変更を報告せずにベースラインを作り直します。下の内容ハッシュ比較も有効にしない限り、ファイルの中身は読みません。','Content-hash comparison for custom plugins'=>'独自プラグインの内容ハッシュ比較','Also compute a content hash for custom/premium plugins and mu-plugin loaders, and report a change even when file size and modified time stay the same.'=>'独自・有料のプラグインと mu-plugin の loader の内容ハッシュも計算し、ファイルサイズと更新日時が同じでも変更を報告する。','Detects a same-size rewrite that preserves the timestamp, which size/timestamp tracking alone cannot catch. This reads file contents on every run and adds I/O cost, so it is off by default; consider enabling it only for sites with a small number of custom plugins. Files larger than a fixed size limit fall back to size/timestamp tracking only.'=>'サイズもタイムスタンプも保ったまま書き換えるケースを検出できます。サイズ・タイムスタンプの追跡だけでは検出できません。実行のたびにファイルの中身を読み、I/O の負荷が増えるため既定では無効です。独自プラグインが少ないサイトだけで有効にすることをお勧めします。一定のサイズを超えるファイルは、サイズ・タイムスタンプの追跡だけに戻ります。','Unrecorded version change alerts'=>'記録のないバージョン変更のアラート','Alert on version changes that did not go through the WordPress updater.'=>'WordPress の更新機構を通らないバージョン変更をアラートで知らせる。','Turn this off on sites that deploy via git, FTP, or Composer, where legitimate version changes never produce an update event.'=>'git・FTP・Composer でデプロイするサイトでは、正当なバージョン変更でも更新イベントが発生しないため、この設定を無効にしてください。','History retention'=>'履歴の保持期間','Delete run history, per-target results and findings older than this period. The newest verified result of each target, results still being processed, and records needed to avoid repeating an alert are always kept. The default keeps everything. After you choose a period, older history is removed gradually at the end of the following runs.'=>'この期間より古い実行履歴・対象ごとの結果・検出結果を削除します。各対象の最新の照合結果、処理中の結果、アラートの重複を避けるために必要な記録は、常に残します。既定ではすべて保持します。期間を選ぶと、その後の実行の終わりに、古い履歴が少しずつ削除されます。','GitHub repository mappings'=>'GitHub リポジトリの対応付け','Verify a plugin or theme against the assets of its GitHub Release instead of wordpress.org. One mapping per line: plugin:{slug} or theme:{stylesheet}, then owner/repo, then optionally the start of the asset file name. The Release is found by the installed version (tag "1.2.3" or "v1.2.3"). Plugins and themes that are not listed are verified as before. Invalid lines and repeated targets are dropped when saving; comment lines (starting with #) are not kept. Directories that contain a .git entry are never compared with GitHub.'=>'wordpress.org の代わりに、GitHub Release のアセットでプラグインまたはテーマを照合します。1行に1件、plugin:{slug} または theme:{stylesheet}、続けて owner/repo、必要ならアセットのファイル名の先頭部分を書きます。Release はインストール済みのバージョンから探します(タグは "1.2.3" または "v1.2.3")。一覧にないプラグインとテーマは、今までどおり照合します。不正な行と重複した対象は保存時に捨てられ、コメント行(# で始まる行)は保存されません。.git を含むディレクトリは GitHub と照合しません。','Also mapped by the wpcv_github_mappings filter: %s'=>'wpcv_github_mappings フィルターによる対応付けもあります: %s','Warning:'=>'警告:','These themes are bundled with WordPress core, so their mappings are ignored and they are verified against wordpress.org and the core checksums: %s'=>'これらのテーマは WordPress コアに同梱されているため、対応付けは無視され、wordpress.org とコアのチェックサムで照合されます: %s','GitHub token'=>'GitHub トークン','A token is configured (WPCV_GITHUB_TOKEN or the wpcv_github_token filter). Its value is never shown or stored in the database.'=>'トークンが設定されています(WPCV_GITHUB_TOKEN または wpcv_github_token フィルター)。値は表示せず、データベースにも保存しません。','No token is configured.'=>'トークンは設定されていません。','Public repositories work without one, but unauthenticated GitHub API requests have a low rate limit. For private repositories or a higher limit, define WPCV_GITHUB_TOKEN in wp-config.php.'=>'公開リポジトリはトークンなしでも使えますが、認証なしの GitHub API はレート制限が低くなります。非公開リポジトリや上限の引き上げが必要な場合は、wp-config.php で WPCV_GITHUB_TOKEN を定義してください。','The GitHub rate limit has been reached. GitHub is not contacted until %s (UTC).'=>'GitHub のレート制限に達しました。%s(UTC)まで GitHub に問い合わせません。','Alert recipients'=>'アラートの宛先','Email addresses that receive an alert when new or resolved findings appear. One per line (commas and semicolons also work). Invalid addresses are dropped when saving. If empty, no alert is sent and a warning is shown in the admin screens.'=>'新規または解消の検出結果が出たときにアラートを受け取るメールアドレスです。1行に1件(カンマ・セミコロン区切りも使えます)。不正なアドレスは保存時に捨てられます。空の場合はアラートを送らず、管理画面に警告を表示します。','Save Changes'=>'変更を保存','Send test alert'=>'テストアラートを送信','Test alert sent successfully.'=>'テストアラートを送信しました。','Alert recipients is empty. Set at least one address above and save, then try again.'=>'アラートの宛先が空です。上でアドレスを1件以上設定して保存してから、もう一度お試しください。','Test alert failed to send.'=>'テストアラートの送信に失敗しました。','Test alert failed to send: %s'=>'テストアラートの送信に失敗しました: %s','Send a test email to the alert recipients above, to confirm the address is correct before relying on it.'=>'上のアラートの宛先にテストメールを送り、アドレスが正しいことを確認します。','Run now'=>'今すぐ実行','Start a verification run immediately instead of waiting for the daily schedule.'=>'毎日の予定を待たず、すぐに検証の実行を始めます。','REST API token (run)'=>'REST API トークン(実行)','New token generated. Copy it now — it will not be shown again:'=>'新しいトークンを発行しました。今すぐコピーしてください。再表示はできません:','A token is defined via the WPCV_REST_TOKEN constant and takes precedence over any token generated here.'=>'WPCV_REST_TOKEN 定数でトークンが定義されています。ここで発行したトークンより優先されます。','A token has been issued. Generating a new one immediately invalidates the previous token.'=>'トークンは発行済みです。新しく発行すると、以前のトークンはすぐに無効になります。','No token has been issued yet. External systems need this token to call POST /wp-json/wpcv/v1/run.'=>'まだトークンが発行されていません。外部のシステムが POST /wp-json/wpcv/v1/run を呼ぶには、このトークンが必要です。','Generate new token'=>'新しいトークンを発行','REST API token (read-only)'=>'REST API トークン(読み取り専用)','A read-only token has been issued. Generating a new one immediately invalidates the previous one.'=>'読み取り専用トークンは発行済みです。新しく発行すると、以前のトークンはすぐに無効になります。','No read-only token has been issued yet. External systems need this (separate) token to call GET /wp-json/wpcv/v1/status and GET /wp-json/wpcv/v1/findings — it cannot start a run.'=>'まだ読み取り専用トークンが発行されていません。外部のシステムが GET /wp-json/wpcv/v1/status と GET /wp-json/wpcv/v1/findings を呼ぶには、(別の)このトークンが必要です。実行を始めることはできません。','Generate new read-only token'=>'新しい読み取り専用トークンを発行','WP-Cron is disabled on this site (DISABLE_WP_CRON). Use WP-CLI (`wp wpcv run`) or the REST endpoint instead.'=>'このサイトでは WP-Cron が無効です(DISABLE_WP_CRON)。代わりに WP-CLI(`wp wpcv run`)か REST エンドポイントを使ってください。','Line %d: the target must look like plugin:{slug} or theme:{stylesheet}. Skipped.'=>'%d 行目: 対象は plugin:{slug} または theme:{stylesheet} の形式にしてください。スキップしました。','Line %d: the repository must look like owner/repo. Skipped.'=>'%d 行目: リポジトリは owner/repo の形式にしてください。スキップしました。','Line %d: this target is already mapped on an earlier line. Skipped.'=>'%d 行目: この対象は、前の行で対応付け済みです。スキップしました。','Line %d: expected "target owner/repo" with an optional asset name. Skipped.'=>'%d 行目: 「対象 owner/repo」の形式で、必要ならアセット名を続けてください。スキップしました。','Keep forever'=>'無期限に保持','%d month'=>'%d か月','A verification run (#%d) is already in progress. Please wait for it to finish.'=>'検証の実行(#%d)がすでに進行中です。終わるまでお待ちください。','Disabled (DISABLE_WP_CRON)'=>'無効(DISABLE_WP_CRON)','Enabled'=>'有効','Current run'=>'現在の実行','Last completed run'=>'直近に完了した実行','Next scheduled run'=>'次回の予定実行','WP-Cron'=>'WP-Cron','Action Scheduler'=>'Action Scheduler','Available'=>'利用可能','Not available (async run falls back to a synchronous run)'=>'利用不可(非同期の実行は同期の実行に切り替わります)','Last WP-CLI run'=>'直近の WP-CLI 実行','Never observed on this site (this only reflects runs recorded here, not whether WP-CLI is installed).'=>'このサイトでは確認されていません(ここに記録された実行だけを反映しており、WP-CLI がインストールされているかどうかではありません)。','None'=>'なし','#%1$d (%2$s) — pending: %3$d, retry: %4$d, findings: %5$d, last activity: %6$s — diff: %7$s, alert: %8$s'=>'#%1$d(%2$s)— 待機: %3$d, 再試行: %4$d, 検出結果: %5$d, 最終動作: %6$s — 差分: %7$s, アラート: %8$s','The suppression rule has been revoked.'=>'抑制ルールを取り消しました。','No suppression rules have been created yet.'=>'まだ抑制ルールが作成されていません。','Type'=>'種類','Created by'=>'作成者','Created at'=>'作成日時','Active'=>'有効','Revoked at %1$s (%2$s)'=>'%1$s に取り消し(%2$s)','version changed'=>'バージョンの変更','User #%d'=>'ユーザー #%d','Revoke reason (required, max 24 chars)'=>'取り消しの理由(必須、24文字まで)','Revoke'=>'取り消す','Invalid suppression rule id.'=>'抑制ルールの ID が不正です。','This rule could not be revoked (it may already be revoked, or no longer exists).'=>'このルールは取り消せませんでした(すでに取り消し済みか、存在しない可能性があります)。','[WPCV] %1$s: %2$s target(s) cannot be compared with the source'=>'[WPCV] %1$s: %2$s 件の照合対象を照合元と比較できません','[WPCV] %1$s: %2$s version change(s) without a WordPress update'=>'[WPCV] %1$s: WordPress の更新を経ないバージョン変更 %2$s 件','[WPCV] %1$s: %2$s new findings, %3$s resolved'=>'[WPCV] %1$s: 新規の検出結果 %2$s 件、解消 %3$s 件','Run #%1$s (%2$s UTC, %3$s)'=>'実行 #%1$s(%2$s UTC、%3$s)','Targets: %1$s verified / %2$s change-tracked / %3$s unverifiable / %4$s failed'=>'照合対象: チェックサム照合済み %1$s / 変更を追跡 %2$s / 照合できない %3$s / 失敗 %4$s','New: %1$s  Resolved: %2$s  Continuing: %3$s (already reported)'=>'新規: %1$s  解消: %2$s  継続: %3$s(報告済み)','Top %d by severity:'=>'重大度の高い順に上位 %d 件:','By target:'=>'照合対象別:','Resolved:'=>'解消:','Version changed without a WordPress update:'=>'WordPress の更新を経ずにバージョンが変わりました:','Not verified today (baseline rebuilt after a version change):'=>'本日は照合していません(バージョン変更後にベースラインを作り直しました):','Cannot compare with the source (the GitHub token is invalid, expired or lacks permission). These targets are monitored by file-change tracking meanwhile:'=>'照合元と比較できません(GitHub のトークンが無効・失効している、または権限が足りません)。次の照合対象は、その間ファイルの変化(stat 差分検知)で監視しています:','(new)'=>'(新規)','Check the GitHub token (the WPCV_GITHUB_TOKEN constant or the wpcv_github_token filter).'=>'GitHub のトークン(WPCV_GITHUB_TOKEN 定数または wpcv_github_token フィルター)を確認してください。','Unverifiable %d times in a row:'=>'%d 回連続で照合できませんでした:','Removed targets: %s'=>'削除された照合対象: %s','Details: %s'=>'詳細: %s','[WPCV] %1$s: %2$s runs failed in a row'=>'[WPCV] %1$s: 実行が %2$s 回連続で失敗しました','%d runs failed in a row:'=>'実行が %d 回連続で失敗しました:','Manifest not found (including not yet published)'=>'マニフェストが見つかりません(未公開を含む)','HTTP error while fetching'=>'取得時の HTTP エラー','GitHub rate limit reached'=>'GitHub のレート制限に達しました','Cannot access the source (the GitHub token is invalid, expired or lacks permission)'=>'照合元にアクセスできません(GitHub のトークンが無効・失効している、または権限が足りません)','ZipArchive extension is not available'=>'ZipArchive 拡張が利用できません','Distribution package not found (e.g. child theme)'=>'配布パッケージが見つかりません(例: 子テーマ)','GitHub release has no asset'=>'GitHub の Release にアセットがありません','Could not uniquely determine the asset'=>'アセットを1つに特定できませんでした','Could not identify a verification source'=>'照合ソースを特定できませんでした','Could not determine the local version'=>'ローカルのバージョンを特定できませんでした','Archive is corrupt or failed verification'=>'アーカイブが壊れている、または検証に失敗しました','Archive rejected (zip slip / zip bomb check)'=>'アーカイブを拒否しました(zip slip / zip bomb の検査)','Insufficient disk space for extraction'=>'展開に必要なディスクの空き容量が足りません','Version changed during verification (will retry)'=>'検証中にバージョンが変わりました(再試行します)','Time budget exhausted (will resume)'=>'時間予算を使い切りました(続きから再開します)','Target no longer found locally'=>'照合対象がローカルに見つかりません','Worker lease expired too many times'=>'ワーカーのリースが何度も期限切れになりました','Excluded by an exclude_target suppression rule'=>'exclude_target の抑制ルールで除外されています','Skipped: already verified by checksums'=>'スキップ: すでにチェックサムで照合済みです','Stat baseline rebuilt after a version change (changes in this run were not compared)'=>'バージョン変更後に stat ベースラインを作り直しました(この実行では変更を比較していません)','Version changed without a record of a WordPress update'=>'WordPress の更新の記録がないままバージョンが変わりました','WP Checksum Verifier requires PHP %1$s or higher and WordPress %2$s or higher. You have PHP %3$s and WordPress %4$s.'=>'WP Checksum Verifier を使うには PHP %1$s 以上と WordPress %2$s 以上が必要です。現在は PHP %3$s、WordPress %4$s です。','Plugin Activation Error'=>'プラグインの有効化エラー','Invalid value for parameter: %s'=>'パラメーターの値が不正です: %s','The verifier is busy. Try again shortly.'=>'検証処理がビジーです。しばらくしてからもう一度お試しください。','The verification run failed. Check the run history for details.'=>'検証の実行に失敗しました。詳細は実行履歴を確認してください。','Too many failed authentication attempts. Try again later.'=>'認証の失敗が多すぎます。しばらくしてからもう一度お試しください。','Invalid or missing REST token.'=>'REST トークンが無効、または指定されていません。','[WPCV] Test alert from %s'=>'[WPCV] %s からのテストアラート','This is a test alert from WP Checksum Verifier. If you received this message, your alert recipient setting is working correctly.'=>'これは WP Checksum Verifier からのテストアラートです。このメッセージが届いていれば、アラートの宛先の設定は正しく動作しています。','GitHub'=>'GitHub']];